// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

/// @notice Minimal ERC20 surface used by this contract.
interface IERC20 {
    function transfer(address to, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// @notice Uniswap SwapRouter02 (IV3SwapRouter) exact-input single-hop surface.
/// @dev SwapRouter02's params struct has NO `deadline` field (unlike the original SwapRouter).
interface ISwapRouter02 {
    struct ExactInputSingleParams {
        address tokenIn;
        address tokenOut;
        uint24 fee;
        address recipient;
        uint256 amountIn;
        uint256 amountOutMinimum;
        uint160 sqrtPriceLimitX96;
    }

    function exactInputSingle(ExactInputSingleParams calldata params)
        external
        payable
        returns (uint256 amountOut);
}

/// @title DCA
/// @notice Dollar-cost-averaging buyer: anyone can fund it with `tokenIn`, only the
///         owner can trigger swaps into `tokenOut` or withdraw funds.
contract DCA {
    address public immutable router;
    address public immutable tokenIn;
    address public immutable tokenOut;
    uint24 public immutable fee;

    address public owner;

    event Deposited(address indexed from, uint256 amount);
    event Bought(uint256 amountIn, uint256 amountOut);
    event Withdrawn(address indexed token, uint256 amount);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    error NotOwner();
    error ZeroAddress();
    error ZeroAmount();
    error InsufficientOutput(uint256 amountOut, uint256 minOut);
    error TransferFailed();
    error ApprovalFailed();

    modifier onlyOwner() {
        if (msg.sender != owner) revert NotOwner();
        _;
    }

    constructor(address router_, address tokenIn_, address tokenOut_, uint24 fee_) {
        if (router_ == address(0) || tokenIn_ == address(0) || tokenOut_ == address(0)) {
            revert ZeroAddress();
        }
        router = router_;
        tokenIn = tokenIn_;
        tokenOut = tokenOut_;
        fee = fee_;
        owner = msg.sender;
        emit OwnershipTransferred(address(0), msg.sender);
    }

    /// @notice Pull `amount` of tokenIn from the caller into this contract.
    /// @dev Caller must have approved this contract for at least `amount` of tokenIn.
    function deposit(uint256 amount) external {
        if (amount == 0) revert ZeroAmount();
        _safeTransferFrom(tokenIn, msg.sender, address(this), amount);
        emit Deposited(msg.sender, amount);
    }

    /// @notice Swap exactly `amountIn` of tokenIn for at least `minOut` of tokenOut.
    ///         The bought tokens remain in this contract.
    function buy(uint256 amountIn, uint256 minOut) external onlyOwner {
        if (amountIn == 0) revert ZeroAmount();

        // Approve exactly what this swap needs, then clear any dust allowance after.
        _safeApprove(tokenIn, router, amountIn);

        uint256 amountOut = ISwapRouter02(router).exactInputSingle(
            ISwapRouter02.ExactInputSingleParams({
                tokenIn: tokenIn,
                tokenOut: tokenOut,
                fee: fee,
                recipient: address(this),
                amountIn: amountIn,
                amountOutMinimum: minOut,
                sqrtPriceLimitX96: 0
            })
        );

        // Belt-and-braces: the router already enforces amountOutMinimum.
        if (amountOut < minOut) revert InsufficientOutput(amountOut, minOut);

        _safeApprove(tokenIn, router, 0);

        emit Bought(amountIn, amountOut);
    }

    /// @notice Send `amount` of `token` held by this contract to the owner.
    function withdraw(address token, uint256 amount) external onlyOwner {
        if (token == address(0)) revert ZeroAddress();
        _safeTransfer(token, owner, amount);
        emit Withdrawn(token, amount);
    }

    /// @notice Hand the contract to a new owner.
    function transferOwnership(address newOwner) external onlyOwner {
        if (newOwner == address(0)) revert ZeroAddress();
        address previous = owner;
        owner = newOwner;
        emit OwnershipTransferred(previous, newOwner);
    }

    // --- internal ERC20 helpers (tolerate non-standard tokens that return no data) ---

    function _safeTransfer(address token, address to, uint256 amount) internal {
        (bool ok, bytes memory data) =
            token.call(abi.encodeWithSelector(IERC20.transfer.selector, to, amount));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }

    function _safeTransferFrom(address token, address from, address to, uint256 amount) internal {
        (bool ok, bytes memory data) =
            token.call(abi.encodeWithSelector(IERC20.transferFrom.selector, from, to, amount));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert TransferFailed();
    }

    function _safeApprove(address token, address spender, uint256 amount) internal {
        (bool ok, bytes memory data) =
            token.call(abi.encodeWithSelector(IERC20.approve.selector, spender, amount));
        if (!ok || (data.length != 0 && !abi.decode(data, (bool)))) revert ApprovalFailed();
    }
}

