// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

/// @notice Share vault hardened against the "first depositor / donation" (share
///         price inflation) attack.
///
/// Two fixes, either of which alone kills the exploit; together they are belt
/// and braces:
///
/// 1. INTERNAL ASSET ACCOUNTING. The exchange rate is derived from
///    `totalAssets`, a number that only moves on deposit/withdraw, never from
///    `asset.balanceOf(address(this))`. Tokens shoved straight into the vault
///    therefore do not move the share price at all: a donation is a pure gift
///    to nobody (it is not withdrawable by anyone), so the attack costs the
///    attacker their whole donation and pays them nothing.
///
/// 2. VIRTUAL SHARES/ASSETS OFFSET. Both sides of the ratio carry a +1 virtual
///    unit, so an empty vault has a well-defined 1:1 price and there is no
///    `totalShares == 0` special case to game and no division by zero. Rounding
///    always favours the vault (down on mint, down on redeem), so dust can
///    never be levered into a rate move.
contract Vault {
    IERC20 public immutable asset;

    /// @dev Assets under management, tracked internally. Deliberately NOT
    ///      `asset.balanceOf(address(this))` — that is the inflation vector.
    uint256 public totalAssets;
    uint256 public totalShares;
    mapping(address => uint256) public shares;

    uint256 private constant VIRTUAL_ASSETS = 1;
    uint256 private constant VIRTUAL_SHARES = 1;

    uint256 private locked = 1;

    event Deposit(address indexed who, uint256 assets, uint256 shares);
    event Withdraw(address indexed who, uint256 shares, uint256 assets);

    modifier nonReentrant() {
        require(locked == 1, "reentrant");
        locked = 2;
        _;
        locked = 1;
    }

    constructor(address _asset) {
        require(_asset != address(0), "asset=0");
        asset = IERC20(_asset);
    }

    function deposit(uint256 amount) external nonReentrant returns (uint256 s) {
        require(amount > 0, "amount=0");

        // Rounds down: the vault never mints more shares than the deposit earns.
        s = (amount * (totalShares + VIRTUAL_SHARES)) / (totalAssets + VIRTUAL_ASSETS);
        require(s > 0, "zero shares");

        shares[msg.sender] += s;
        totalShares += s;
        totalAssets += amount;

        _pull(msg.sender, amount);
        emit Deposit(msg.sender, amount, s);
    }

    function withdraw(uint256 s) external nonReentrant returns (uint256 amount) {
        require(s > 0, "shares=0");

        // Rounds down: the vault never pays out more than the shares are worth.
        amount = (s * (totalAssets + VIRTUAL_ASSETS)) / (totalShares + VIRTUAL_SHARES);

        shares[msg.sender] -= s; // reverts on underflow (0.8.x checked math)
        totalShares -= s;
        totalAssets -= amount;

        _push(msg.sender, amount);
        emit Withdraw(msg.sender, s, amount);
    }

    /// @notice Assets a given share balance is currently redeemable for.
    function convertToAssets(uint256 s) external view returns (uint256) {
        return (s * (totalAssets + VIRTUAL_ASSETS)) / (totalShares + VIRTUAL_SHARES);
    }

    /// @notice Shares a given deposit would currently mint.
    function convertToShares(uint256 amount) external view returns (uint256) {
        return (amount * (totalShares + VIRTUAL_SHARES)) / (totalAssets + VIRTUAL_ASSETS);
    }

    function _pull(address from, uint256 amount) private {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeWithSelector(IERC20.transferFrom.selector, from, address(this), amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "transferFrom failed");
    }

    function _push(address to, uint256 amount) private {
        (bool ok, bytes memory data) = address(asset).call(
            abi.encodeWithSelector(IERC20.transfer.selector, to, amount)
        );
        require(ok && (data.length == 0 || abi.decode(data, (bool))), "transfer failed");
    }
}
